function safeUrl(value, fallback='#') {
  try { const url = new URL(value, location.origin); return ['http:','https:'].includes(url.protocol) ? (url.origin === location.origin || /^(?:www\.)?ecolelesage\.com$/i.test(url.hostname) ? `${url.pathname}${url.search}${url.hash}` : url.href) : fallback; } catch { return fallback; }
}

function cleanContent(html) {
  if(!html) return '';
  const doc = new DOMParser().parseFromString(String(html), 'text/html');
  doc.querySelectorAll('script,style,iframe,form,input,button,select,textarea,object,embed').forEach(el=>el.remove());
  doc.querySelectorAll('*').forEach(el=>{
    for(const attr of [...el.attributes]) if(/^on/i.test(attr.name)||['style','class','id','width','height','loading'].includes(attr.name)) el.removeAttribute(attr.name);
    if(el.tagName==='A') {
      const href=el.getAttribute('href')||'';
      if(!href || href.startsWith('#')) { el.replaceWith(...el.childNodes);return; }
      const cleaned=safeUrl(href,'');
      if(!cleaned)el.removeAttribute('href');else el.setAttribute('href',cleaned);
      if(/^https?:/.test(cleaned)){el.setAttribute('target','_blank');el.setAttribute('rel','noopener noreferrer');}
    }
    if(el.tagName==='IMG'){el.setAttribute('loading','lazy');el.setAttribute('alt',el.getAttribute('alt')||'');el.setAttribute('src',safeUrl(el.getAttribute('src')||'',''));}
  });
  return doc.body.innerHTML;
}

