  async function onSubmit(event){const form=event.target;if(!(form instanceof HTMLFormElement)||!form.matches('[data-shop-checkout]'))return;event.preventDefault();if(submitting)return;error='';const errorBox=root.querySelector('[data-shop-checkout-error]');errorBox.hidden=true;if(!form.checkValidity()){errorBox.textContent=t.invalid;errorBox.hidden=false;form.reportValidity();return;}for(const [key,value]of new FormData(form))formState[key]=value;formState.terms=form.elements.terms.checked;submitting=true;const button=form.querySelector('button[type=submit]');button.disabled=true;button.textContent=t.submitting;const previousIds=new Set((store.state?.orders||[]).map(o=>o.id));try{const billing=Object.fromEntries(['firstName','lastName','email','phone'].map(key=>[key,String(formState[key]||'').trim()]));const beneficiary=formState.recipient==='gift'?{firstName:formState.giftFirstName.trim(),lastName:formState.giftLastName.trim(),email:formState.giftEmail.trim()}:undefined;await store.dispatch('checkout',{billing,beneficiary,terms:!!formState.terms,language:lang});const order=(store.state?.orders||[]).find(o=>!previousIds.has(o.id))||(store.state?.orders||[]).filter(o=>o.studentId===actorStudent()).at(-1);if(!order)throw Error(t.failure);clearCheckoutDraft(filterOwner);conversion('purchase',{orderId:order.id});navigate('confirmation',{orderId:order.id});}catch(problem){if(disposed)return;submitting=false;error=problem?.code==='EXISTING_PROFILE'?t.existingProfileError:problem?.message||t.failure;renderCheckout();const box=root.querySelector('[data-shop-checkout-error]');if(box){box.hidden=false;box.textContent=error;box.scrollIntoView({block:'nearest'});}}}
